        self.left = left
        self.right = right

def tsum(root: Optional[TreeNode]) -> int:
    if not root:
        return 0
    return root.val + tsum(root.left) + tsum(root.right)

def fun(root: Optional[TreeNode], total: int, mx: list) -> int:
    if not root:
        return 0
    left = fun(root.left, total, mx)
    right = fun(root.right, total, mx)
    subtree = left + right + root.val
    mx[0] = max(mx[0], subtree * (total - subtree))
    return subtree

