class Solution:
    def fib(self, n: int) -> int:
        # Base cases
        if n <= 0:
            return 0
        if n == 1:
            return 1
        # Memoization / DP array
        memo = [0] * (n + 1)
        memo[0] = 0
        memo[1] = 1
        # Fill DP table bottom‑up
        for i in range(2, n + 1):
            memo[i] = memo[i - 1] + memo[i - 2]
        return memo[n]

