class Solution:
    def minimumPartition(self, s: str, k: int) -> int:
        ans = 0
        cur = 0
        for ch in s:
            digit = ord(ch) - ord('0')
            if digit > k:
                return -1
            if cur * 10 + digit > k:
                ans += 1
                cur = digit
            else:
                cur = cur * 10 + digit
        if cur > 0:
            ans += 1
        return ans

